package com.ci.pipeline

import akka.actor.ActorSystem
import akka.http.scaladsl.Http
import akka.http.scaladsl.model._
import akka.http.scaladsl.server.Directives._
import akka.stream.ActorMaterializer
import java.io.{File, PrintWriter}
import java.nio.file.{Files, Paths, Path}
import scala.concurrent.ExecutionContextExecutor
import scala.sys.process._
import java.util.Base64

object PipelineController {
  implicit val system: ActorSystem = ActorSystem("ci-pipeline")
  implicit val materializer: ActorMaterializer = ActorMaterializer()
  implicit val executionContext: ExecutionContextExecutor = system.dispatcher

  val WORKSPACE_ROOT = "/var/ci/workspace"
  val NGINX_INCLUDES_DIR = "/etc/nginx/conf.d/includes"
  val ALLOWED_EXTENSIONS = Set(".yml", ".yaml", ".json", ".conf", ".html")

  // Sanitize path components to prevent directory traversal
  def sanitizePath(component: String): String = {
    component.replaceAll("\\.\\.", "").replaceAll("[/\\\\]", "_")
  }

  // Validate that content doesn't contain shell injection patterns
  def validateContent(content: String): Boolean = {
    val shellPatterns = List("`", "$(", "&&", "||", ";", "\n")
    !shellPatterns.exists(content.contains)
  }

  // Neutralize SSI directives by escaping HTML comment sequences
  def neutralizeSSI(input: String): String = {
    input.replaceAll("<!--", "&lt;!--").replaceAll("-->", "--&gt;")
  }

  // Template rendering for build status pages served by nginx
  // Uses a layered approach: first renders metadata, then writes to nginx include dir
  def renderBuildStatusPage(buildId: String, metadata: Map[String, String]): String = {
    val sanitizedBuildId = sanitizePath(buildId)
    val templateBase = loadTemplate("build_status")

    // Apply metadata substitutions using our safe template engine
    val rendered = applyTemplateSubstitutions(templateBase, metadata)
    rendered
  }

  def loadTemplate(name: String): String = {
    val templatePath = s"$WORKSPACE_ROOT/templates/$name.html"
    if (Files.exists(Paths.get(templatePath))) {
      new String(Files.readAllBytes(Paths.get(templatePath)))
    } else {
      "<html><body><h1>Build: {{BUILD_ID}}</h1><p>Status: {{STATUS}}</p><p>{{DETAILS}}</p></body></html>"
    }
  }

  // Template substitution engine - replaces {{KEY}} with values
  // Security: we validate keys against an allowlist and neutralize SSI in values
  def applyTemplateSubstitutions(template: String, values: Map[String, String]): String = {
    val allowedKeys = Set("BUILD_ID", "STATUS", "DETAILS", "TIMESTAMP", "BRANCH", "COMMIT_MSG")
    var result = template
    values.foreach { case (key, value) =>
      if (allowedKeys.contains(key.toUpperCase)) {
        // Neutralize any SSI directives in user-provided values before substitution
        val safeValue = neutralizeSSI(value)
        result = result.replace(s"{{$key}}", safeValue)
      }
    }
    result
  }

  // Writes rendered content to nginx includes directory for serving
  // This is picked up by nginx with SSI enabled (ssi on; in nginx.conf)
  def publishBuildPage(buildId: String, content: String): Either[String, String] = {
    val sanitizedId = sanitizePath(buildId)
    val outputPath = s"$NGINX_INCLUDES_DIR/$sanitizedId.html"

    // Validate the output path is within expected directory
    val resolvedPath = Paths.get(outputPath).normalize()
    if (!resolvedPath.startsWith(NGINX_INCLUDES_DIR)) {
      return Left("Path traversal detected")
    }

    val writer = new PrintWriter(new File(outputPath))
    try {
      writer.write(content)
      Right(outputPath)
    } finally {
      writer.close()
    }
  }

  // Encoding layer: build metadata comes from k8s annotations which are base64 encoded
  def decodeBuildMetadata(encoded: String): Map[String, String] = {
    try {
      val decoded = new String(Base64.getDecoder.decode(encoded), "UTF-8")
      // Parse simple key=value format, one per line
      decoded.split("\\r?\\n").flatMap { line =>
        val parts = line.split("=", 2)
        if (parts.length == 2) Some(parts(0).trim -> parts(1).trim)
        else None
      }.toMap
    } catch {
      case _: Exception => Map.empty
    }
  }

  // The nginx configuration has: ssi on; ssi_types text/html;
  // Files in NGINX_INCLUDES_DIR are served with SSI processing enabled
  // This means <!--#include virtual="/etc/passwd" --> or
  // <!--#exec cmd="id" --> directives in HTML will be processed by nginx

  val route = path("api" / "v1" / "builds" / Segment / "publish") { buildId =>
    post {
      entity(as[String]) { body =>
        val metadata = decodeBuildMetadata(body)

        // Security check: validate no shell injection in values
        val allValuesClean = metadata.values.forall(validateContent)
        if (!allValuesClean) {
          complete(StatusCodes.BadRequest -> "Invalid characters in metadata")
        } else {
          val rendered = renderBuildStatusPage(buildId, metadata)
          publishBuildPage(buildId, rendered) match {
            case Right(path) => complete(StatusCodes.OK -> s"Published to $path")
            case Left(err) => complete(StatusCodes.Forbidden -> err)
          }
        }
      }
    }
  }

  def main(args: Array[String]): Unit = {
    Http().bindAndHandle(route, "0.0.0.0", 8080)
    println("CI Pipeline controller started on port 8080")
  }
}
